@tool
extends "res://addons/godot_agent/api/agent_tool.gd"

func _description() -> String:
	return "Echoes the text back. For the checks-test."

func _parameters() -> Dictionary:
	return {"properties": {"text": {"type": "string"}}, "required": ["text"]}

func _run(args: Dictionary, ctx: RefCounted) -> Variant:
	return "echo: " + str(args.text)
